    for did, pairs in titles.items():
        lessons = []
        for title, concepts, code, walkthrough, pitfalls, try_it in pairs:
            # code is the worked example code; walkthrough separate
            lessons.append(L(title, did, concepts, code, walkthrough, pitfalls, try_it))
